@spec mm_blob_wide_spec  src=tests/specs/mm_blob_wide_spec.lua  loc=100  sha=8cc9255  cases=6
@exercises midiBlob (midiBlob)
@surface   midiBlob.render, midiBlob.buildWire, midiBlob.parse

# Intent
  14-bit CC lives in the codec, not a registry: a fractional cc val on a code
  in 0..31 splits to an MSB(shaped)/LSB(step) wire pair on serialise and
  coalesces back on parse. The value's type is the whole signal -- integer val
  stays a plain 7-bit CC, one wire event.

# Helpers
  @fn wireCCs(blob)  @ 11-23
      -- Raw channel-voice CC events straight off the blob, no coalescing.
  @fn ccOf(extra)  @ 25-29
  @fn ser(notes, ccs, texts, passthrough)  @ 31-33

# Cases
  @case 'fractional cc in 0..31 serialises to an MSB(shaped)/LSB(step) wire pair'  [pure]  @ 37-47
  @case 'the wire pair coalesces back to one fractional record (round-trip)'  [pure]  @ 51-57
  @case 'carrier-style value (14-bit around 8192) round-trips exactly'  [pure]  @ 61-67
  @case 'integer cc in 0..31 stays a plain 7-bit CC: one wire event'  [pure]  @ 71-78
  @case 'a lone LSB-range code (>= 32) with no MSB partner stays independent'  [pure]  @ 82-88
  @case 'bezier wide cc keeps its tension on the MSB across the round-trip'  [pure]  @ 92-98

# Uses (outbound edges)
  @use call midiBlob.render  @ 32
  @use call midiBlob.buildWire  @ 32
  @use call midiBlob.parse  @ 54,64,76,85,95

# Fields (r read / w write incl. constructor keys)
  @field r cc  @ 21,42,44,86
  @field w cc  @ 18,27,84
  @field w chan  @ 27
  @field w evType  @ 27
  @field w idx  @ 27
  @field w name  @ 37,51,61,71,82,92
  @field r ppq  @ 21,46
  @field w ppq  @ 18,27
  @field w run  @ 38,52,62,72,83,93
  @field r shape  @ 43,45,96
  @field w shape  @ 18,27,63,73,84,94
  @field r tension  @ 97
  @field w tension  @ 94
  @field r val  @ 42,44,66,77,87
  @field w val  @ 18,27,63,73,84
